/**
 * List.Item: one item: a title, with a leading mark, a description, a meta and a trailing control.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  SlotOutlet,
  SlotTemplate,
  classes,
  derived,
  useMember,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/list.module.css'

/** List.Item: one item: a title, with a leading mark, a description, a meta and a trailing control: the inputs it takes, by the React member's prop names. */
export interface ListItemProps {
  /**
   * The item whose page or detail is open. At most one per list. It has no effect on an item
   * that is only read, which has no link or button to say it to a screen reader.
   */
  current?: boolean
  /**
   * One supporting line under the title. It wraps and is never clipped.
   */
  description?: string
  /**
   * The item navigates: the title is a link whose target covers the row.
   */
  href?: string
  /**
   * A short trailing fact the application has already formatted: a time, a count.
   */
  meta?: string
  /**
   * The item's name, and the accessible name of its link or button.
   */
  title: string
}

/** List.Item: one item: a title, with a leading mark, a description, a meta and a trailing control. */
@Component({
  selector: 'li[pmListItem]',
  encapsulation: ViewEncapsulation.None,
  host: {
    '[attr.class]': 'e1()',
    '[attr.data-interactive]': 'e2()',
    '[attr.data-current]': 'e3()',
  },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate],
  // prettier-ignore
  template: `<ng-template pmSlot="leading" [pmSlotOf]="$"><ng-content select="[slot=leading]" /></ng-template>
<ng-template pmSlot="trailing" [pmSlotOf]="$"><ng-content select="[slot=trailing]" /></ng-template>
@if (e4()) {<span
[attr.class]="e5()"
><ng-container [pmSlotOutlet]="'leading'" [pmSlotOf]="$" /></span>}
<span
[attr.class]="e6()"
>@if (e7()) {<!-- link -->
<a
[attr.class]="e8()"
[attr.href]="e9()"
[attr.aria-current]="e10()"
(click)="h1($event)"
>{{ e11() }}</a>} @else if (e12()) {<!-- button -->
<button
[attr.class]="e13()"
type="button"
[attr.aria-current]="e14()"
(click)="h2()"
>{{ e15() }}</button>} @else {<span
[attr.class]="e16()"
>{{ e17() }}</span>}
@if (e18()) {<span
[attr.class]="e19()"
>{{ e20() }}</span>}</span>
@if (e21()) {<span
[attr.class]="e22()"
>{{ e23() }}</span>}
@if (e24()) {<span
[attr.class]="e25()"
><ng-container [pmSlotOutlet]="'trailing'" [pmSlotOf]="$" /></span>}`,
})
export class ListItem {
  /**
   * The item whose page or detail is open. At most one per list. It has no effect on an item
   * that is only read, which has no link or button to say it to a screen reader.
   */
  readonly current = input<Exclude<ListItemProps['current'], undefined>, ListItemProps['current']>(
    false,
    { transform: (value: ListItemProps['current']) => (value === undefined ? false : value) },
  )
  /**
   * One supporting line under the title. It wraps and is never clipped.
   */
  readonly description = input<ListItemProps['description']>(undefined)
  /**
   * The item navigates: the title is a link whose target covers the row.
   */
  readonly href = input<ListItemProps['href']>(undefined)
  /**
   * A short trailing fact the application has already formatted: a time, a count.
   */
  readonly meta = input<ListItemProps['meta']>(undefined)
  /**
   * The item's name, and the accessible name of its link or button.
   */
  readonly title = input.required<ListItemProps['title']>()
  /**
   * The app's router, on an item with an `href`, as on Link (`link.md` §Routing): a click that
   * would navigate this tab calls it in place of the browser.
   */
  readonly onNavigate = output<string>({ alias: 'navigate' })
  /**
   * The item is picked. Without an `href` the title is a button whose target covers the row.
   * With one it is also called on every click of the link, one that opens a new tab included, so
   * a router uses `onNavigate` there.
   */
  readonly onSelect = output<void>({ alias: 'select' })
  protected readonly $ = useMember({
    element: 'pmListItem',
    events: ['navigate', 'select'],
    props: {
      current: () => this.current(),
      description: () => this.description(),
      href: () => this.href(),
      meta: () => this.meta(),
      title: () => this.title(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly navigatesHere = derived(
    () =>
      (event: MouseEvent): boolean =>
        !event.defaultPrevented &&
        event.button === 0 &&
        !event.metaKey &&
        !event.ctrlKey &&
        !event.shiftKey &&
        !event.altKey,
  )
  protected readonly route = derived(() => (event: MouseEvent): void => {
    if (
      this.$p.href === undefined ||
      !this.$.listening(this.onNavigate, 'onNavigate') ||
      !this.navigatesHere.value(event)
    )
      return
    event.preventDefault()
    this.$.emit(this.onNavigate, 'onNavigate', this.$p.href)
  })

  protected e1() {
    return styles.item
  }

  protected e2() {
    return this.$p.href !== undefined || this.$.listening(this.onSelect, 'onSelect')
      ? ''
      : undefined
  }

  protected e3() {
    return this.$p.current &&
      (this.$p.href !== undefined || this.$.listening(this.onSelect, 'onSelect'))
      ? ''
      : undefined
  }

  protected e4() {
    return this.$.filled('leading')
  }

  protected e5() {
    if (!this.$.filled('leading')) return undefined as never
    return styles.leading
  }

  protected e6() {
    return styles.text
  }

  protected e7() {
    return this.$p.href !== undefined
  }

  protected e8() {
    if (!(this.$p.href !== undefined)) return undefined as never
    return classes(styles.title, styles.primary)
  }

  protected e9() {
    if (!(this.$p.href !== undefined)) return undefined as never
    return this.$p.href
  }

  protected e10() {
    if (!(this.$p.href !== undefined)) return undefined as never
    return this.$p.current ? 'page' : undefined
  }

  protected h1($event: MouseEvent): void {
    if (!(this.$p.href !== undefined)) return
    void (this.$.emit(this.onSelect, 'onSelect'), this.route.value($event))
  }

  protected e11() {
    if (!(this.$p.href !== undefined)) return undefined as never
    return this.$p.title
  }

  protected e12() {
    if (this.$p.href !== undefined) return undefined as never
    return this.$.listening(this.onSelect, 'onSelect')
  }

  protected e13() {
    if (this.$p.href !== undefined) return undefined as never
    if (!this.$.listening(this.onSelect, 'onSelect')) return undefined as never
    return classes(styles.title, styles.primary)
  }

  protected e14() {
    if (this.$p.href !== undefined) return undefined as never
    if (!this.$.listening(this.onSelect, 'onSelect')) return undefined as never
    return this.$p.current ? 'true' : undefined
  }

  protected h2(): void {
    if (this.$p.href !== undefined) return
    if (!this.$.listening(this.onSelect, 'onSelect')) return
    this.$.emit(this.onSelect, 'onSelect')
  }

  protected e15() {
    if (this.$p.href !== undefined) return undefined as never
    if (!this.$.listening(this.onSelect, 'onSelect')) return undefined as never
    return this.$p.title
  }

  protected e16() {
    if (this.$p.href !== undefined) return undefined as never
    if (this.$.listening(this.onSelect, 'onSelect')) return undefined as never
    return styles.title
  }

  protected e17() {
    if (this.$p.href !== undefined) return undefined as never
    if (this.$.listening(this.onSelect, 'onSelect')) return undefined as never
    return this.$p.title
  }

  protected e18() {
    return this.$p.description !== undefined
  }

  protected e19() {
    if (!(this.$p.description !== undefined)) return undefined as never
    return styles.description
  }

  protected e20() {
    if (!(this.$p.description !== undefined)) return undefined as never
    return this.$p.description
  }

  protected e21() {
    return this.$p.meta !== undefined
  }

  protected e22() {
    if (!(this.$p.meta !== undefined)) return undefined as never
    return styles.meta
  }

  protected e23() {
    if (!(this.$p.meta !== undefined)) return undefined as never
    return this.$p.meta
  }

  protected e24() {
    return this.$.filled('trailing')
  }

  protected e25() {
    if (!this.$.filled('trailing')) return undefined as never
    return styles.trailing
  }
}
